/* ============================================
   PROMPT SUGGESTIONS COMPONENT
   Horizontal row of tappable prompt chips.
   Scrolls with pure-CSS edge fades by default;
   wraps for empty-state hero placements.
   ============================================ */

.ds-prompt-suggestions {
  display: flex;
  gap: var(--gap-200);
  /* Breathing room so chip focus rings aren't clipped by the scroll box */
  padding-block: var(--padding-050);
}

/* ============================================
   SIZE
   The pill scale itself is Chip's — the row only
   picks which size to ask for. What belongs here
   is the gutter between pills, which opens up a
   step at the larger size.
   ============================================ */

.ds-prompt-suggestions--default {
  gap: var(--gap-300);
}

.ds-prompt-suggestions--compact {
  /* Base gap applies. */
}

/* ============================================
   SCROLL — one line, overflow hinted by fades
   ============================================ */

/* Edge fades — scroll layout only, which is why the layout is named on the
   element rather than inferred: content near either edge fades out, hinting
   there is more to scroll. A CSS mask, not a scroll listener.
   ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
.ds-prompt-suggestions--scroll {
  overflow-x: auto;
  -webkit-mask-image: linear-gradient(
    to right,
    transparent,
    black var(--gap-500),
    black calc(100% - var(--gap-500)),
    transparent
  );
  mask-image: linear-gradient(
    to right,
    transparent,
    black var(--gap-500),
    black calc(100% - var(--gap-500)),
    transparent
  );
}

/* ============================================
   WRAP — multi-line hero variant, no fades
   ============================================ */

.ds-prompt-suggestions--wrap {
  flex-wrap: wrap;
}

/* ============================================
   STACK — one suggestion per line
   For narrow columns, where a wrapped row breaks
   wherever the labels happen to run out of room
   and the ragged right edge reads as an accident.
   Pills still hug their labels: stretching them
   to a shared width would make a set of prompts
   look like a set of buttons.
   ============================================ */

.ds-prompt-suggestions--stack {
  flex-direction: column;
  align-items: flex-start;
}

/* ============================================
   TILES and CARDS — blocks for a home screen
   Where the chip layouts are a line of prompts,
   these are a row of places to start: an even
   grid that folds as the row's own width narrows,
   so a docked panel folds while a full-width page
   does not.
   ============================================ */

/* The column floor is stated on the icon scale, the one size both blocks
   are drawn from: a tile is never narrower than three cover icons, a card
   than four. Four tiles or three cards sit in one row on a conversation
   column and fold to two columns and one on a phone, with no breakpoint. */
.ds-prompt-suggestions--tiles,
.ds-prompt-suggestions--cards {
  display: grid;
}

.ds-prompt-suggestions--tiles {
  grid-template-columns: repeat(auto-fit, minmax(calc(var(--icon-size-1200) * 3), 1fr));
}

.ds-prompt-suggestions--cards {
  grid-template-columns: repeat(auto-fit, minmax(calc(var(--icon-size-1200) * 4), 1fr));
}

.ds-prompt-suggestions--tiles .ds-prompt-suggestions__item,
.ds-prompt-suggestions--cards .ds-prompt-suggestions__item {
  flex-shrink: 1;
  min-width: 0;
}

/* One surface for both blocks: a hairline round a container that lets the
   page through, blurred so text stays on a calm field over an ambient
   background. The navigation-tile radius, per the radius scale. */
.ds-prompt-suggestions__tile,
.ds-prompt-suggestions__card {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  margin: 0;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  background-color: var(--color-bg-container-primary-semi);
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

/* A tile answers the pointer quietly, in place: the fill firms up to the
   solid container and the hairline steps up to the tertiary text ink, so
   the block reads as picked out without moving. */
.ds-prompt-suggestions__tile {
  transition:
    background-color var(--motion-duration-fast) var(--motion-ease-standard),
    border-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-prompt-suggestions__tile:hover {
  background-color: var(--color-bg-container-primary);
  border-color: var(--color-text-tertiary);
}

/* A card lifts: the Card component's own hover, the same rise and the same
   sanctioned shadow, so a prompt card and a navigation tile answer the
   pointer the same way. */
.ds-prompt-suggestions__card {
  transition:
    transform var(--motion-duration-slow) var(--motion-ease-standard),
    box-shadow var(--motion-duration-slow) var(--motion-ease-standard);
  /* ds-allow(color): transparent resting state of the sanctioned Card
     hover-lift shadow (see design.md — Do's and Don'ts). */
  box-shadow: 0 0 0 rgba(0, 0, 0, 0);
}

.ds-prompt-suggestions__card:hover {
  transform: translateY(-4px);
  /* ds-allow(color): the sanctioned Card hover-lift shadow, restated so the
     two tiles lift alike (see design.md — Do's and Don'ts). */
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

/* The pending shells are not targets, so they neither lift nor light. */
.ds-prompt-suggestions__tile--pending:hover {
  background-color: var(--color-bg-container-primary-semi);
  border-color: var(--color-bg-container-border);
}

.ds-prompt-suggestions__card--pending:hover {
  transform: none;
  box-shadow: none;
}

.ds-prompt-suggestions__tile:focus-visible,
.ds-prompt-suggestions__card:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-prompt-suggestions__tile {
  gap: var(--gap-300);
  padding: var(--padding-400);
}

.ds-prompt-suggestions__card {
  gap: var(--gap-200);
  padding: var(--padding-200) var(--padding-200) var(--padding-400);
}

.ds-prompt-suggestions__text {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  min-width: 0;
}

.ds-prompt-suggestions__card .ds-prompt-suggestions__text {
  padding-inline: var(--padding-200);
}

.ds-prompt-suggestions__label {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

.ds-prompt-suggestions__description {
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  letter-spacing: var(--font-caption-letter-spacing);
  color: var(--color-text-tertiary);
}

.ds-prompt-suggestions__icon {
  display: inline-flex;
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-secondary);
}

/* The card's cover: a wash of one pixel ink, strong at the top and nearly
   gone by the floor, with the subject's icon standing in it in the same
   ink. The inks cycle by position, so a row of cards is told apart by
   colour as well as by title, and they are the theme-split set, so the icon
   holds its contrast in both modes. */
.ds-prompt-suggestions__cover {
  display: flex;
  align-items: center;
  justify-content: center;
  /* Twice the cover icon's own size: the icon scale sets the proportion. */
  height: calc(var(--icon-size-1200) * 2);
  border-radius: var(--radius-400);
  background-image: linear-gradient(
    to bottom,
    color-mix(in srgb, var(--ds-prompt-suggestions-tint) 24%, transparent),
    color-mix(in srgb, var(--ds-prompt-suggestions-tint) 6%, transparent)
  );
}

.ds-prompt-suggestions__cover .ds-prompt-suggestions__icon {
  --icon-size: var(--icon-size-1200);
  color: var(--ds-prompt-suggestions-tint);
}

.ds-prompt-suggestions__item:nth-child(6n + 1) { --ds-prompt-suggestions-tint: var(--color-pixel-ink-4); }
.ds-prompt-suggestions__item:nth-child(6n + 2) { --ds-prompt-suggestions-tint: var(--color-pixel-ink-1); }
.ds-prompt-suggestions__item:nth-child(6n + 3) { --ds-prompt-suggestions-tint: var(--color-pixel-ink-2); }
.ds-prompt-suggestions__item:nth-child(6n + 4) { --ds-prompt-suggestions-tint: var(--color-pixel-ink-5); }
.ds-prompt-suggestions__item:nth-child(6n + 5) { --ds-prompt-suggestions-tint: var(--color-pixel-ink-6); }
.ds-prompt-suggestions__item:nth-child(6n) { --ds-prompt-suggestions-tint: var(--color-pixel-ink-3); }

/* Pending blocks: the real shell holding the label's bar, so the row keeps
   its height when the suggestions land. */
.ds-prompt-suggestions__tile--pending,
.ds-prompt-suggestions__card--pending {
  cursor: default;
  font-size: var(--font-paragraph-sm-emphasis-size);
}

.ds-prompt-suggestions__tile--pending {
  justify-content: flex-end;
  min-height: calc(
    var(--icon-size-600) + var(--gap-300) + var(--font-paragraph-sm-emphasis-line-height) +
      var(--font-caption-line-height) + 2 * var(--padding-400)
  );
}

/* A pending card stands as tall as the loaded one it holds room for: the
   cover, the label line, and two lines of description (the longest a card's
   question runs at this width), so the row does not grow when they land. */
.ds-prompt-suggestions__card--pending {
  min-height: calc(
    var(--icon-size-1200) * 2 + var(--gap-200) + var(--font-paragraph-sm-emphasis-line-height) +
      var(--gap-050) + 2 * var(--font-caption-line-height) + var(--padding-200) +
      var(--padding-400) + 2 * var(--border-025)
  );
}

.ds-prompt-suggestions__card--pending .ds-prompt-suggestions__skeleton-bar {
  margin: var(--padding-150) var(--padding-200);
  width: auto;
}

/* The chosen block takes the same press-and-spring the chips do. */
.ds-prompt-suggestions__item--chosen .ds-prompt-suggestions__tile,
.ds-prompt-suggestions__item--chosen .ds-prompt-suggestions__card {
  animation: ds-prompt-suggestions-choose var(--motion-duration-slow) var(--motion-ease-spring);
}

/* ============================================
   ITEMS
   ============================================ */

.ds-prompt-suggestions__item {
  display: flex;
  flex-shrink: 0;
  /* Pills pop in one after another — a small rise-and-settle with the
     spring's overshoot, quiet enough to read as arrival rather than
     performance. `backwards` keeps a delayed pill invisible until its
     turn. The pending placeholders and the chips that replace them are
     both items, so each set lands one-two-three. */
  animation: ds-prompt-suggestions-pop var(--motion-duration-slow) var(--motion-ease-spring)
    backwards;
}

/* A set that has already landed stands still: the host turns the entrance
   off (`entrance={false}`) when it re-shows suggestions the visitor has
   already watched arrive, so a reopened panel does not replay them. */
.ds-prompt-suggestions--still .ds-prompt-suggestions__item {
  animation: none;
}

/* The stagger: one instant per pill, capped at the fifth so a long
   scrolling row does not keep the far end waiting. */
.ds-prompt-suggestions__item:nth-child(2) {
  animation-delay: var(--motion-duration-instant);
}

.ds-prompt-suggestions__item:nth-child(3) {
  animation-delay: calc(var(--motion-duration-instant) * 2);
}

.ds-prompt-suggestions__item:nth-child(4) {
  animation-delay: calc(var(--motion-duration-instant) * 3);
}

.ds-prompt-suggestions__item:nth-child(n + 5) {
  animation-delay: calc(var(--motion-duration-instant) * 4);
}

@keyframes ds-prompt-suggestions-pop {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

/* ============================================
   CHOSEN — the tap acknowledgment
   The picked chip presses in and springs back
   (the spring's overshoot is the tiny bounce)
   while its siblings dim, so the choice pops
   for the beat before the host acts on it.
   ============================================ */

.ds-prompt-suggestions__item {
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-prompt-suggestions--choosing
  .ds-prompt-suggestions__item:not(.ds-prompt-suggestions__item--chosen) {
  /* The system's dimmed convention, shared with disabled states. */
  opacity: 0.4;
}

.ds-prompt-suggestions__item--chosen .ds-chip {
  animation: ds-prompt-suggestions-choose var(--motion-duration-slow) var(--motion-ease-spring);
}

@keyframes ds-prompt-suggestions-choose {
  0% {
    transform: scale(1);
  }

  35% {
    transform: scale(0.94);
  }

  /* The spring overshoots past 1 on the way back, then settles. */
  100% {
    transform: scale(1);
  }
}

/* ============================================
   PENDING — placeholder pills
   Each placeholder is the chip's real shell —
   its surface, border, padding and height for
   the row's size — holding a text-height shimmer
   bar where the label is "generating" (Skeleton's
   sweep on ThreadPanel's 0.75em bar geometry).
   The shell is what keeps the row's height and
   rhythm exactly what the loaded chips will be.
   ============================================ */

.ds-prompt-suggestions__skeleton {
  display: flex;
  align-items: center;
  box-sizing: border-box;
  border-radius: var(--radius-pill);
  /* Chip's own surface, so only the label reads as loading. */
  background-color: var(--color-bg-page-primary);
  border: var(--border-025) solid var(--color-bg-container-border);

  /* Chip's default (32px) geometry — the row's compact size. The height is
     the chip's line box plus its padding and border, stated rather than
     grown from text, since the shell holds a bar instead of a label. */
  padding: var(--padding-150) var(--padding-300);
  height: calc(
    var(--font-paragraph-sm-emphasis-line-height) + 2 * var(--padding-150) + 2 * var(--border-025)
  );
  font-size: var(--font-paragraph-sm-emphasis-size);

  /* Widths are em-cycled below so the set reads as questions of different
     lengths rather than three identical pills — a drawing choice scaled by
     the font, like ThreadPanel's 0.75em shimmer bar, not a spacing token. */
  width: 13em;
  max-width: 100%;
}

/* Chip's large geometry — the row's default size. */
.ds-prompt-suggestions--default .ds-prompt-suggestions__skeleton {
  padding: var(--padding-200) var(--padding-500);
  height: calc(
    var(--font-paragraph-emphasis-line-height) + 2 * var(--padding-200) + 2 * var(--border-025)
  );
  font-size: var(--font-paragraph-emphasis-size);
}

.ds-prompt-suggestions__item:nth-child(3n + 2) .ds-prompt-suggestions__skeleton {
  width: 16em;
}

.ds-prompt-suggestions__item:nth-child(3n) .ds-prompt-suggestions__skeleton {
  width: 11em;
}

/* The generating "label": a text-height bar filling the shell's content
   box, swept by the shimmer. */
.ds-prompt-suggestions__skeleton-bar {
  display: block;
  width: 100%;
  height: 0.75em;
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-secondary);
  position: relative;
  overflow: hidden;
  /* The trailing end dissolves, as ThreadPanel's naming bar does under its
     title mask — a label mid-write, not a finished block.
     ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
  -webkit-mask-image: linear-gradient(to right, black calc(100% - var(--gap-1000)), transparent);
  mask-image: linear-gradient(to right, black calc(100% - var(--gap-1000)), transparent);
}

.ds-prompt-suggestions__skeleton-bar::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-bg-container-primary) 50%,
    transparent 100%
  );
  /* ds-allow(motion): Skeleton's shimmer — the sweep needs a symmetric
     in-out curve no --motion-ease-* token provides; the duration is
     tokenized. */
  animation: ds-prompt-suggestions-shimmer var(--motion-duration-loop-shimmer)
    ease-in-out infinite;
}

@keyframes ds-prompt-suggestions-shimmer {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

'use client';

import React from 'react';
import { Chip } from '../Chip/Chip';
import { MOTION_EXIT_SYNC_MS } from '../../tokens/motion';
import './PromptSuggestions.css';
import '../../fonts/material-symbols.css';

/** One tappable suggestion in the row. */
export interface PromptSuggestion {
  /** Stable identifier passed to `onValueChange`. */
  id: string;
  /** The suggestion text shown in the chip. */
  label: string;
  /** Optional leading icon — Material Symbol name (string) or custom element (ReactNode). In the `cards` layout it stands in the card's cover. */
  icon?: string | React.ReactNode;
  /** A quiet second line under the label, drawn by the `tiles` and `cards` layouts: what the tile leads to, or the full question a card asks. The chip layouts have no room for it and leave it out. */
  description?: string;
}

/** Props owned by PromptSuggestions itself — everything else falls through to the root element. */
type PromptSuggestionsOwnProps = {
  /** The suggestions to render, in order. */
  suggestions: PromptSuggestion[];
  /** Fires with the tapped suggestion's `id`, one acknowledgment beat after the tap — the chosen chip pulses and its siblings dim first, so the choice is seen even when selection unmounts the row. */
  onValueChange?: (id: string) => void;
  /**
   * How the suggestions are arranged. `scroll` is one line that scrolls
   * sideways behind edge fades. `wrap` runs them across as many lines as
   * they need, for empty-state hero placements. `stack` gives each one its
   * own line, for narrow columns where a wrapped row breaks unevenly and
   * the ragged right edge reads as an accident. `tiles` and `cards` leave
   * the chip behind for an empty-state home screen: `tiles` is an even row
   * of quiet blocks, each an icon over a label and its `description`;
   * `cards` gives each suggestion a tinted cover holding its icon, with the
   * label and description beneath. Both fold to fewer columns as their own
   * width narrows.
   */
  layout?: 'scroll' | 'wrap' | 'stack' | 'tiles' | 'cards';
  /**
   * Legacy alias for `layout="wrap"`; ignored when `layout` is set.
   * @deprecated Use `layout` instead, which also covers `stack`.
   */
  wrap?: boolean;
  /**
   * The suggestions are still being generated: shimmer placeholder pills
   * hold their place, matching the current size's chip geometry so nothing
   * shifts when the real chips land. While pending the given `suggestions`
   * are not rendered, the placeholders are hidden from assistive technology,
   * and the row reports `aria-busy` instead.
   */
  pending?: boolean;
  /** How many placeholder pills the pending state holds space with. */
  pendingCount?: number;
  /**
   * Play the staggered pop-in when the items mount. On by default; a host
   * re-showing a set that has already landed (reopening a panel over the
   * same suggestions) turns it off, so the chips stand where they were
   * instead of arriving twice.
   */
  entrance?: boolean;
  /**
   * Row scale. `default` sits at the body-paragraph scale, so a suggestion
   * reads at the same weight as the messages it will become; `compact` is
   * the quieter row for placements alongside a live conversation.
   */
  size?: 'default' | 'compact';
  /** Accessible name for the list. */
  ariaLabel?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface PromptSuggestionsProps
  extends PromptSuggestionsOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof PromptSuggestionsOwnProps> {}

/**
 * PromptSuggestions is a horizontal row of tappable prompts for starting or
 * steering a conversation. Each suggestion renders as a clickable Chip, so
 * one component owns the pill look; the row scrolls horizontally with pure
 * CSS edge fades — no scroll listeners, no measurement — or wraps for
 * empty-state hero placements.
 */
export const PromptSuggestions = React.forwardRef<HTMLDivElement, PromptSuggestionsProps>(
  (
    {
      suggestions,
      onValueChange,
      layout,
      wrap = false,
      pending = false,
      pendingCount = 3,
      entrance = true,
      size = 'default',
      ariaLabel = 'Suggested prompts',
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-prompt-suggestions';

    /* The tap acknowledgment: the chosen chip gives one small spring pulse
       while its siblings dim, and `onValueChange` fires one beat later —
       so a host that unmounts the row on selection (a chat sending the
       suggestion) still lets the choice be seen. One choice at a time:
       taps are ignored while a beat is in flight, which also guards a
       double-tap firing twice. The chosen state clears when the pulse
       finishes, so a row that persists (follow-ups under an old answer)
       returns to normal and stays tappable. */
    const [chosenId, setChosenId] = React.useState<string | null>(null);
    const chooseTimer = React.useRef<number | null>(null);
    React.useEffect(
      () => () => {
        if (chooseTimer.current) window.clearTimeout(chooseTimer.current);
      },
      [],
    );
    const choose = (id: string) => {
      /* The ref guards the same-tick double-tap the state cannot see yet. */
      if (chosenId || chooseTimer.current) return;
      setChosenId(id);
      chooseTimer.current = window.setTimeout(() => {
        chooseTimer.current = null;
        onValueChange?.(id);
      }, MOTION_EXIT_SYNC_MS);
    };

    // `layout` wins outright, so a caller migrating off `wrap` never has to
    // remove it in the same edit to get the arrangement they asked for.
    const arrangement = layout ?? (wrap ? 'wrap' : 'scroll');

    /* The row sits one step above Chip's own scale: a conversation starter is
       something to tap, not metadata about something else. Chip still owns
       the pill look — the row only picks which of its sizes to ask for. */
    const chipSize = size === 'compact' ? 'default' : 'large';

    /* Tiles and cards are blocks rather than pills, so they draw their own
       button instead of composing Chip. Everything around the item — the
       list semantics, the pending and entrance beats, the tap
       acknowledgment — is the row's and stays shared. */
    const block = arrangement === 'tiles' ? 'tile' : arrangement === 'cards' ? 'card' : null;
    const renderIcon = (icon: PromptSuggestion['icon']) =>
      typeof icon === 'string' ? (
        <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
          {icon}
        </span>
      ) : (
        <span className={`${baseClass}__icon`} aria-hidden="true">
          {icon}
        </span>
      );

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      `${baseClass}--${arrangement}`,
      chosenId ? `${baseClass}--choosing` : '',
      entrance ? '' : `${baseClass}--still`,
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <div
        {...rest}
        ref={ref}
        className={classes}
        role="list"
        aria-label={ariaLabel}
        /* aria-busy is load-bearing while pending: the placeholders are
           aria-hidden, and a busy list is exempt from the required-children
           rule that an otherwise empty role="list" would fail. */
        aria-busy={pending || undefined}
        data-pending={pending || undefined}
      >
        {pending
          ? Array.from({ length: pendingCount }, (_, index) => (
              <div key={index} aria-hidden="true" className={`${baseClass}__item`}>
                {/* The chip's shell with a text-height shimmer bar where the
                    label will be: the label generating, not the pill. */}
                {block ? (
                  /* The block's own shell, holding the label's bar. */
                  <span className={`${baseClass}__${block} ${baseClass}__${block}--pending`}>
                    {block === 'card' && <span className={`${baseClass}__cover`} />}
                    <span className={`${baseClass}__skeleton-bar`} />
                  </span>
                ) : (
                  <span className={`${baseClass}__skeleton`}>
                    <span className={`${baseClass}__skeleton-bar`} />
                  </span>
                )}
              </div>
            ))
          : suggestions.map((suggestion) => (
              <div
                key={suggestion.id}
                role="listitem"
                className={`${baseClass}__item${
                  chosenId === suggestion.id ? ` ${baseClass}__item--chosen` : ''
                }`}
                /* The pulse finishing is what ends the chosen state — no
                   second timer. The entrance animation also ends here, so
                   filter by name. */
                onAnimationEnd={(event) => {
                  if (event.animationName === 'ds-prompt-suggestions-choose') {
                    setChosenId(null);
                  }
                }}
              >
                {block ? (
                  <button
                    type="button"
                    className={`${baseClass}__${block}`}
                    onClick={() => choose(suggestion.id)}
                  >
                    {block === 'card' ? (
                      <span className={`${baseClass}__cover`}>
                        {suggestion.icon != null && renderIcon(suggestion.icon)}
                      </span>
                    ) : (
                      suggestion.icon != null && renderIcon(suggestion.icon)
                    )}
                    <span className={`${baseClass}__text`}>
                      <span className={`${baseClass}__label`}>{suggestion.label}</span>
                      {suggestion.description && (
                        <span className={`${baseClass}__description`}>
                          {suggestion.description}
                        </span>
                      )}
                    </span>
                  </button>
                ) : (
                  <Chip
                    label={suggestion.label}
                    icon={suggestion.icon}
                    size={chipSize}
                    onClick={() => choose(suggestion.id)}
                  />
                )}
              </div>
            ))}
      </div>
    );
  },
);

PromptSuggestions.displayName = 'PromptSuggestions';
